		dir := t.TempDir()
		entries := append(sourceSubmit("a", 0, 1),
			successResultAt("a", 1, 0),
			&logEntry{T: kindSubmit, Seq: 1, ID: "b", From: "a", To: "b", Nonce: 2, ProofAt: 10},
			successResultAt("b", 2, 0),
		)
